"""Saved-offer cash schedule entry and conserved financial execution display."""
HTML = '''<section class="card" id="so-cash-panel" hidden><h2>PLAN DE COBROS Y PAGOS DE LA OFERTA</h2><p id="so-cash-title"></p><p>Los cobros incluyen IVA y deben sumar el total de la oferta. Declara por separado los pagos de logística, regalos u otros costes, con su importe de caja y fecha: no se deducen de los costes netos del análisis comercial.</p><p>Si un movimiento ya está en la previsión, selecciónalo: se comprobarán tipo, fecha, moneda e importe y no se sumará de nuevo.</p><form id="so-cash-form"><div id="so-cash-rows"></div><button id="so-cash-add" type="button">+ Añadir cobro o pago</button><label>Responsable declarado<input id="so-cash-actor" maxlength="128" required></label><label><input id="so-cash-ack" type="checkbox" required style="width:auto;display:inline"> Confirmo que son declaraciones pendientes de validar; no acreditan cobro, pago ni aceptación de la oferta.</label><button id="so-cash-save" class="primary" type="submit">Guardar plan y comprobar con el motor financiero</button><p id="so-cash-notice" role="status"></p></form><div id="so-cash-result"></div></section>'''
JS = r'''
let salesCashState=null,salesCashSequence=0;
function resetSalesCash(){salesCashSequence++;salesCashState=null;$('so-cash-panel').hidden=true;$('so-cash-rows').replaceChildren();$('so-cash-result').replaceChildren();$('so-cash-notice').textContent=''}
async function openSalesCash(id){const seq=++salesCashSequence,dataset=$('dataset').value;try{const data=await api('/api/sales-proposals/cash-plan/read',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,proposal_id:id})});if(seq!==salesCashSequence||dataset!==$('dataset').value)return;salesCashState=data;$('so-cash-form').reset();$('so-cash-rows').replaceChildren();$('so-cash-result').replaceChildren();$('so-cash-notice').textContent=data.can_edit?'':'Esta oferta conserva otro contexto documental. El plan se consulta como histórico; crea una oferta con la versión actual para cambiarlo.';$('so-cash-title').textContent=data.offer.reference+' · Total con IVA '+money(data.offer.total)+' EUR · Revisión del plan '+data.revision;const rows=data.plan?.rows||[{flow_type:'COLLECTION',amount:data.offer.total,due_date:data.offer.due_date,disposition:'NEW_DECLARATION',note:'Cobro propuesto de '+data.offer.reference}];rows.forEach(addSalesCashRow);$('so-cash-save').disabled=!data.can_edit;$('so-cash-add').disabled=!data.can_edit;$('so-cash-panel').hidden=false;renderSalesCashResult(data.plan);$('so-cash-panel').scrollIntoView({behavior:'smooth',block:'start'})}catch(e){if(seq===salesCashSequence)$('so-notice').textContent=e.message}}
function cashField(parent,title,key,options){const label=document.createElement('label');label.textContent=title;const input=document.createElement(options?'select':'input');input.dataset.cash=key;if(options)options.forEach(([value,text])=>option(input,value,text));else{input.type='text';input.maxLength=key==='note'?500:80;input.required=true}label.append(input);parent.append(label);return input}
function addSalesCashRow(initial){if(!salesCashState||$('so-cash-rows').children.length>=30)return;const r=initial?.flow_type?initial:{flow_type:'COLLECTION',amount:'',due_date:'',disposition:'NEW_DECLARATION',note:''};const row=document.createElement('div');row.className='so-line';const fields=document.createElement('div');fields.className='fields';cashField(fields,'Tipo','flow_type',[['COLLECTION','Cobro del cliente'],['PAYMENT','Pago de un coste']]).value=r.flow_type;cashField(fields,'Importe de caja, con impuestos (€)','amount').value=r.amount===''?'':stockNumber(r.amount);cashField(fields,'Vencimiento DD/MM/AAAA','due_date').value=r.due_date?stockDate(r.due_date):'';const disposition=cashField(fields,'Presencia en previsiones','disposition',[['NEW_DECLARATION','Nuevo: pendiente de validar'],['ALREADY_DOCUMENTED','Ya está documentado']]);disposition.value=r.disposition;const existing=cashField(fields,'Movimiento existente (debe coincidir exactamente)','existing_flow_id',[['','Selecciona si ya existe'],...salesCashState.documented_flows.map(f=>[f.record_id,f.record_id+' · '+(f.canonical.flow_type==='COLLECTION'?'Cobro':'Pago')+' · '+money(f.canonical.amount)+' '+(f.canonical.currency||'')+' · '+stockDate(f.canonical.due_date)])]);existing.value=r.existing_flow_id||'';existing.disabled=disposition.value!=='ALREADY_DOCUMENTED';disposition.onchange=()=>{existing.disabled=disposition.value!=='ALREADY_DOCUMENTED';if(existing.disabled)existing.value=''};cashField(fields,'Concepto y fundamento de esta declaración','note').value=r.note;row.append(fields);const distinctLabel=document.createElement('label'),distinct=document.createElement('input');distinct.type='checkbox';distinct.style.width='auto';distinct.dataset.cash='separate_movement_acknowledged';distinct.checked=r.separate_movement_acknowledged===true;distinctLabel.append(distinct,document.createTextNode(' Si coincide con la previsión, declaro que es un movimiento nuevo distinto y lo explico en el concepto.'));row.append(distinctLabel);const remove=document.createElement('button');remove.type='button';remove.textContent='Quitar movimiento';remove.onclick=()=>row.remove();row.append(remove);$('so-cash-rows').append(row)}
function renderSalesCashResult(plan){const box=$('so-cash-result');box.replaceChildren();if(!plan)return;const e=plan.execution;const h=document.createElement('h3');h.textContent='RESULTADO CONSERVADO DEL PLAN';box.append(h);salesAdviceNote(box,'Revisión '+plan.revision+' · Declarado por '+plan.actor+' · '+stockDate(plan.created_at));salesAdviceNote(box,e.message,true);if(e.status==='EXECUTED'){const labels={DETERMINED:'Calculada',NOT_EVIDENCED:'Evidencia pendiente',NOT_EVALUABLE:'No evaluable',CONFLICTING_DATA:'Datos contradictorios'};salesAdviceMetrics(box,[['Proyección documental',labels[e.baseline.projection.status]||e.baseline.projection.status],['Proyección con el plan',labels[e.with_declared_plan.projection.status]||e.with_declared_plan.projection.status],['Movimientos nuevos',stockNumber(e.new_flow_count)],['Ya documentados, sin duplicar',stockNumber(e.reused_flow_count)]]);salesAdviceNote(box,'Horizonte configurado: '+e.finance_input.horizon_days+' días desde '+stockDate(e.finance_input.snapshot.as_of_date)+'. Tesorería mínima configurada: '+money(e.finance_input.treasury_minimum)+' EUR.');}salesAdviceNote(box,'El inventario de costes no se considera completo. El resultado no acredita conciliación, calidad, crédito ni viabilidad de venta. No se han modificado el saldo ni las previsiones documentadas.',true)}
$('so-cash-add').onclick=()=>addSalesCashRow();$('so-cash-form').onsubmit=async event=>{event.preventDefault();if(!salesCashState)return;const dataset=$('dataset').value,seq=salesCashSequence,button=$('so-cash-save');button.disabled=true;$('so-cash-notice').textContent='';try{const rows=Array.from($('so-cash-rows').children).map(row=>{const r=Object.fromEntries(Array.from(row.querySelectorAll('[data-cash]')).map(el=>[el.dataset.cash,el.type==='checkbox'?el.checked:el.value]));return {...r,amount:parameterNumber(r.amount),due_date:inputDateISO(r.due_date)}});const result=await api('/api/sales-proposals/cash-plan',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,proposal_id:salesCashState.offer.proposal_id,revision:salesCashState.revision,documentary_context_fingerprint:salesCashState.documentary_context_fingerprint,actor:$('so-cash-actor').value.trim(),acknowledge:$('so-cash-ack').checked,rows})});if(seq!==salesCashSequence||dataset!==$('dataset').value)return;salesCashState.revision=result.revision;salesCashState.plan=result.plan;$('so-cash-title').textContent=salesCashState.offer.reference+' · Total con IVA '+money(salesCashState.offer.total)+' EUR · Revisión del plan '+result.revision;renderSalesCashResult(result.plan);$('so-cash-notice').textContent='Plan conservado. Las nuevas declaraciones permanecen sin validar.';}catch(e){if(seq===salesCashSequence)$('so-cash-notice').textContent=e.message}finally{if(seq===salesCashSequence)button.disabled=!salesCashState?.can_edit}};
'''
